def increasingTriplet (nums : List Int) (h_precond : increasingTriplet_precond (nums)) : Bool :=
  let nums' := nums.zipIdx
  nums'.all (fun (x, i) =>
    nums'.all (fun (y, j) =>
      nums'.all (fun (z, k) =>
        ¬(i < j ∧ j < k ∧ x < y ∧ y < z)
      )
    )
  ) ∨
  nums'.any (fun (x, i) =>
    nums'.any (fun (y, j) =>
      nums'.any (fun (z, k) =>
        i < j ∧ j < k ∧ x < y ∧ y < z
      )
    )
  )
